class Container {
  constructor() {
    this.factories = {};
    this.instances = {};
  }
  register(token, factory) {
    this.factories[token] = factory;
  }
  resolve(token) {
    if (!this.factories[token]) throw new Error('Not registered: ' + token);
    return this.factories[token]();
  }
}

